119	    @Test
120	    void missingMeasurementAndMultipleReasonsReported() throws Exception {
121	        createCert("INS-1", "1", "0");
122	        submit("R-FAIL", "INS-1", "100", "0", "9", "alice"); // 不合格且提交人=放行人
123	        mvc.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders
124	                        .post("/api/measurements/release")
125	                        .header("X-Actor-Id", "alice")
126	                        .contentType(MediaType.APPLICATION_JSON)
