155	    @Test
156	    void revokingCertificateDropsUsabilityButKeepsHistory() throws Exception {
157	        long certId = createCert("INS-1", "1", "0");
158	        submit("R-1", "INS-1", "1", "0", "9", "alice");
159	        mvc.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders
