package com.example.starter.calibration.service;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.time.Instant;
import java.util.HexFormat;
import java.util.TreeMap;
import java.util.function.Supplier;

import org.springframework.dao.DuplicateKeyException;
import org.springframework.stereotype.Component;
import org.springframework.transaction.support.TransactionTemplate;

import com.example.starter.calibration.api.ApiException;
import com.example.starter.calibration.model.CalcRecord;
import com.example.starter.calibration.repo.CalcRecordRepository;
import com.fasterxml.jackson.databind.ObjectMapper;

/**
 * calcKey 幂等执行器。
 * 在同一事务内执行业务并在成功时占用 calcKey；业务失败抛出则整事务回滚，calcKey 不被占用（失败不占键）。
 * 同 calcKey 且指纹一致时重放首次成功结果；指纹不一致返回 409；并发同键按事务提交顺序裁决，
 * 后提交者唯一键冲突回滚后重放首次结果。
 */
@Component
public class IdempotentExecutor {

    private final CalcRecordRepository records;
    private final TransactionTemplate txTemplate;
    private final ObjectMapper objectMapper;

    public IdempotentExecutor(CalcRecordRepository records,
                             TransactionTemplate txTemplate,
                             ObjectMapper objectMapper) {
        this.records = records;
        this.txTemplate = txTemplate;
        this.objectMapper = objectMapper;
    }

    /** 幂等执行结果。 */
    public record Result<T>(T value, boolean replayed) {
    }

    /**
     * 计算 SHA-256 指纹（十六进制）；content 为调用方组织的规范输入串，
     * 须含测量/批次版本、环境、系数版本与全部输入。
     */
    public static String fingerprint(String operation, String content) {
        try {
            MessageDigest digest = MessageDigest.getInstance("SHA-256");
            byte[] hash = digest.digest((operation + "|" + content).getBytes(StandardCharsets.UTF_8));
            return HexFormat.of().formatHex(hash);
        } catch (Exception ex) {
            throw new IllegalStateException(ex);
        }
    }

    /** 以 TreeMap 组织稳定的键顺序，便于构造可复现指纹内容。 */
    public static TreeMap<String, Object> orderedMap() {
        return new TreeMap<>();
    }

    /**
     * 无 calcKey 时直接在事务内执行业务；有 calcKey 时按指纹重放或占用。
     *
     * @param calcKey      幂等键（空表示不启用）
     * @param operation   操作类型
     * @param fingerprint  指纹内容供应商（事务内、业务执行前后各调一次，须基于稳定的版本/环境/系数版本输入）
     * @param type        成功响应类型（用于重放反序列化）
     * @param action      业务动作（在幂等事务内执行）
     */
    public <T> Result<T> execute(String calcKey, String operation, Supplier<String> fingerprint,
                                Class<T> type, Supplier<T> action) {
        if (calcKey == null || calcKey.isBlank()) {
            return new Result<>(txTemplate.execute(status -> action.get()), false);
        }
        String key = calcKey.trim();
        try {
            return txTemplate.execute(status -> runInTransaction(key, operation, fingerprint, type, action));
        } catch (DuplicateKeyException conflict) {
            // 并发同键：本事务已整体回滚，首次结果已由先提交事务占用；重放首次结果。
            return new Result<>(replay(key, operation, fingerprint, type), true);
        }
    }

    private <T> T runInTransaction(String key, String operation, Supplier<String> fingerprint,
                                    Class<T> type, Supplier<T> action) {
        var existing = records.findByKey(key);
        if (existing.isPresent()) {
            CalcRecord record = existing.get();
            if (!record.operation().equals(operation)) {
                throw ApiException.conflict("IDEMPOTENCY_OPERATION_MISMATCH",
                        "calcKey 已用于其他操作: " + key);
            }
            String current = fingerprint(operation, fingerprint.get());
            if (!record.fingerprint().equals(current)) {
                throw ApiException.conflict("IDEMPOTENCY_FINGERPRINT_MISMATCH",
                        "calcKey 相同但请求指纹不一致: " + key);
            }
            return deserialize(record.responseJson(), type);
        }
        T result = action.get();
        String fp = fingerprint(operation, fingerprint.get());
        String json;
        try {
            json = objectMapper.writeValueAsString(result);
        } catch (Exception ex) {
            throw new IllegalStateException(ex);
        }
        records.insert(new CalcRecord(key, operation, fp, json, Instant.now()));
        return result;
    }

    private <T> T replay(String key, String operation, Supplier<String> fingerprint, Class<T> type) {
        CalcRecord record = records.findByKey(key)
                .orElseThrow(() -> ApiException.conflict("CALC_KEY_BUSY",
                        "calcKey 正被占用: " + key));
        if (!record.operation().equals(operation)) {
            throw ApiException.conflict("IDEMPOTENCY_OPERATION_MISMATCH",
                    "calcKey 已用于其他操作: " + key);
        }
        if (!record.fingerprint().equals(fingerprint(operation, fingerprint.get()))) {
            throw ApiException.conflict("IDEMPOTENCY_FINGERPRINT_MISMATCH",
                    "calcKey 相同但请求指纹不一致: " + key);
        }
        return deserialize(record.responseJson(), type);
    }

    private <T> T deserialize(String json, Class<T> type) {
        try {
            return objectMapper.readValue(json, type);
        } catch (Exception ex) {
            throw new IllegalStateException(ex);
        }
    }
}

