/** 输入之外的版本化部分：证书 ID、系数版本 ID、版本号，追加在输入指纹之后。 */
private String versionFingerprintSuffix(long certificateId, Long coefficientId, int versionNo) {
    return "|cert=" + certificateId
            + "|coefficient=" + (coefficientId == null ? "" : coefficientId)
            + "|version=" + versionNo;
}

/**
 * 重放指纹：基于逻辑测量首版本（提交固化行）与全部输入；必须与首次提交固化指纹一致。
 */
private String replaySubmitFingerprint(ParsedSubmit p) {
    Measurement first = measurements.findChain(p.key()).stream().findFirst()
            .orElseThrow(() -> ApiException.conflict("CALC_KEY_BUSY", "calcKey 正被占用: " + p.calcKey()));
    return p.fingerprintContent()
