        }
        if (e.certificateRevoked) {
            e.structuralReasons.add("CERTIFICATE_REVOKED");
        }
        if (m.submittedBy().equals(ctx.releaser())) {
            e.structuralReasons.add("SAME_ACTOR");
        }
        return e;
    }
