                .andExpect(jsonPath("$.chain[0].compensatedValue").value("5.1"))
                .andExpect(jsonPath("$.chain[1].coefficientId").value(v2));
        java.util.Map<String, Object> first = jdbc.queryForMap(
                "SELECT coefficient_id, compensation_value FROM measurement WHERE root_id <> id AND measurement_key = 'E-V' "
                        + "AND version_no = 1");
        assertEquals(v1, ((Number) first.get("coefficient_id")).longValue());
        assertEquals(new java.math.BigDecimal("0.100000"), first.get("compensation_value"));
        assertEquals(true, newId > 0);
    }

    @Test
    void recalcReassessesGateAndReleasedSnapshotNotRewritten() throws Exception {
        createCert("INS-1", "1", "0");
        publishCoeff("M-1", "0", "0", "0", "0", "40", "0", "100");
        // 已放行的测量：补偿后 5.0
