                                {"keys":["E-R"],"uncertaintyLimit":"1"}"""))
                .andExpect(status().isOk());
        long releasedCoeff = ((Number) jdbc.queryForMap(
                "SELECT coefficient_id FROM measurement WHERE measurement_key='E-R'").get("coefficient_id")).longValue();

